import type { Directory, User } from "./types.ts";

export function grantsFor(user: User, directory: Directory): Set<string> {
  // Resolve each role's grants along with those inherited through its parent chain.
  const grants = new Set<string>();
  for (const name of user.roles) {
    const seen = new Set<string>();
    for (let role = name; role && !seen.has(role); role = directory[role]?.parent ?? "") {
      seen.add(role);
      for (const grant of directory[role]?.grants ?? []) grants.add(grant);
    }
  }
  return grants;
}

